CREATE TABLE `tags` (
  `id` bigint NOT NULL,
  `name` varchar(60) NOT NULL UNIQUE
);
CREATE TABLE `tenants` (
  `id` bigint NOT NULL,
  `name` varchar(120) NOT NULL,
  `slug` varchar(140) NOT NULL UNIQUE,
  `plan` varchar(16) NOT NULL,
  `hq_latitude` decimal(9,6) NOT NULL,
  `hq_longitude` decimal(9,6) NOT NULL,
  `settings` json,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
);
CREATE TABLE `accounts` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `iban` varchar(34) NOT NULL UNIQUE,
  `currency` char(3) NOT NULL,
  `minor_scale` smallint NOT NULL,
  `balance` decimal(20,4) NOT NULL,
  `last_transaction_id` bigint,
  `opened_at` datetime NOT NULL
);
CREATE TABLE `categories` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `parent_id` bigint,
  `name` varchar(120) NOT NULL,
  `depth` integer NOT NULL
);
CREATE TABLE `import_jobs` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `kind` varchar(40) NOT NULL,
  `total` integer NOT NULL,
  `processed` integer NOT NULL,
  `succeeded` integer NOT NULL,
  `failed` integer NOT NULL,
  `pending` integer NOT NULL,
  `status` varchar(16) NOT NULL,
  `completed_at` datetime
);
CREATE TABLE `payments` (
  `id` bigint NOT NULL,
  `account_id` bigint NOT NULL,
  `order_id` bigint,
  `amount_minor` bigint NOT NULL,
  `running_balance` decimal(20,4) NOT NULL,
  `method` varchar(16) NOT NULL,
  `reference` varchar(32) NOT NULL,
  `sequence_no` bigint NOT NULL,
  `paid_at` datetime NOT NULL
);
CREATE TABLE `products` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `category_id` bigint,
  `name` varchar(200) NOT NULL,
  `sku` varchar(32) NOT NULL,
  `currency` char(3) NOT NULL,
  `unit_price` decimal(12,2) NOT NULL,
  `cost` decimal(12,4) NOT NULL,
  `weight_g` integer,
  `image_name` varchar(255),
  `image_ext` varchar(8),
  `image_mime` varchar(80),
  `image_size` bigint,
  `image_hash` char(64),
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
);
CREATE TABLE `tasks` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `parent_id` bigint,
  `assignee_id` bigint,
  `title` varchar(200) NOT NULL,
  `status` varchar(16) NOT NULL,
  `depth` integer NOT NULL,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `closed_at` datetime,
  `deleted_at` datetime
);
CREATE TABLE `taggables` (
  `id` bigint NOT NULL,
  `tag_id` bigint NOT NULL,
  `taggable_type` varchar(24) NOT NULL,
  `taggable_id` bigint NOT NULL
);
CREATE TABLE `users` (
  `id` bigint NOT NULL,
  `uuid` char(36) NOT NULL UNIQUE,
  `ulid` char(26) NOT NULL UNIQUE,
  `nanoid` varchar(21) NOT NULL UNIQUE,
  `first_name` varchar(80) NOT NULL,
  `last_name` varchar(80) NOT NULL,
  `full_name` varchar(160) NOT NULL,
  `username` varchar(40) NOT NULL UNIQUE,
  `email` varchar(255) NOT NULL UNIQUE,
  `password_hash` varchar(255) NOT NULL,
  `api_key` varchar(64),
  `phone` varchar(32),
  `address_line1` varchar(200),
  `address_line2` varchar(200),
  `city` varchar(120),
  `region` varchar(120),
  `postcode` varchar(12),
  `country` varchar(2),
  `user_agent` varchar(255),
  `locale` varchar(8) NOT NULL,
  `karma` decimal(18,6) NOT NULL,
  `signature` blob,
  `created_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL,
  `deleted_at` datetime
);
CREATE TABLE `memberships` (
  `tenant_id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `role` varchar(20) NOT NULL,
  `joined_at` datetime NOT NULL
);
CREATE TABLE `orders` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `buyer_id` bigint NOT NULL,
  `reference` varchar(24) NOT NULL UNIQUE,
  `currency` char(3) NOT NULL,
  `subtotal` decimal(14,2) NOT NULL,
  `discount_total` decimal(14,2) NOT NULL,
  `tax_total` decimal(14,2) NOT NULL,
  `shipping_total` decimal(14,2) NOT NULL,
  `grand_total` decimal(14,2) NOT NULL,
  `status` varchar(16) NOT NULL,
  `placed_at` datetime NOT NULL,
  `updated_at` datetime NOT NULL
);
CREATE TABLE `activity_log` (
  `id` bigint NOT NULL,
  `tenant_id` bigint NOT NULL,
  `causer_id` bigint,
  `subject_type` varchar(24) NOT NULL,
  `subject_id` bigint NOT NULL,
  `event` varchar(40) NOT NULL,
  `properties` json,
  `created_at` datetime NOT NULL
);
CREATE TABLE `comments` (
  `id` bigint NOT NULL,
  `author_id` bigint NOT NULL,
  `commentable_type` varchar(24) NOT NULL,
  `commentable_id` bigint NOT NULL,
  `body` text NOT NULL,
  `created_at` datetime NOT NULL
);
CREATE TABLE `attachments` (
  `id` bigint NOT NULL,
  `attachable_type` varchar(24) NOT NULL,
  `attachable_id` bigint NOT NULL,
  `file_name` varchar(255) NOT NULL,
  `extension` varchar(8) NOT NULL,
  `mime_type` varchar(80) NOT NULL,
  `size_bytes` bigint NOT NULL,
  `sha256` char(64) NOT NULL,
  `uploaded_at` datetime NOT NULL
);
CREATE TABLE `order_items` (
  `id` bigint NOT NULL,
  `order_id` bigint NOT NULL,
  `product_id` bigint,
  `description` varchar(200) NOT NULL,
  `quantity` integer NOT NULL,
  `unit_price` decimal(14,2) NOT NULL,
  `discount_amount` decimal(14,2) NOT NULL,
  `tax_amount` decimal(14,2) NOT NULL,
  `line_total` decimal(14,2) NOT NULL
);
CREATE TABLE `sessions` (
  `id` bigint NOT NULL,
  `user_id` bigint NOT NULL,
  `started_at` datetime NOT NULL,
  `ended_at` datetime,
  `duration_seconds` integer,
  `is_active` TINYINT(1) NOT NULL,
  `ip_address` varchar(45) NOT NULL
);
